/**
 * The image fixture registry: the one place that knows where a synthetic
 * fixture lives.
 *
 * A golden case names a fixture id, never a path. That is the whole point of
 * this module: benchmark data must not become an arbitrary filesystem-read
 * contract, so the loader resolves an id through a closed table and refuses
 * anything the table does not hold. Moving the fixture directory is then a
 * change to this file rather than a rewrite of every case.
 *
 * Every fixture is a synthetic raster generated by this repository. No patient
 * photograph, no downloaded clinical image, and no image of unclear provenance
 * belongs here — the evaluation measures a structured observation pipeline, and
 * it can do that with a shape and a colour.
 *
 * @module @deepseek-ai/dsh-medical-eval
 */

import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import type { ImageMediaType } from '@deepseek-ai/dsh-attachment'
import { GoldenCaseError } from './runtime.ts'

/** One registry entry: the id a case names and the file it resolves to. */
interface FixtureEntry {
  /** Registry id a golden case writes in `fixture`. */
  readonly id: string
  /** Leaf file name inside the fixture directory. Never a path. */
  readonly file: string
  /** Media type the attachment service will verify the bytes against. */
  readonly mediaType: ImageMediaType
  /** What the image shows, for a reader of the roster. */
  readonly description: string
}

/**
 * The closed fixture table.
 *
 * Ordered for readers. Three synthetic images cover what the roster needs: one
 * unmistakable subject a real observer can describe, one second subject so two
 * images in a session cannot be confused, and one deliberately unresolvable
 * field.
 */
const FIXTURES: readonly FixtureEntry[] = [
  {
    id: 'synthetic-visible-patch',
    file: 'synthetic-visible-patch.png',
    mediaType: 'image/png',
    description: 'A hard-edged red disc centred on a near-white field: one unmistakable, describable subject.',
  },
  {
    id: 'synthetic-second-view',
    file: 'synthetic-second-view.png',
    mediaType: 'image/png',
    description: 'A filled blue square on a near-white field: a second subject, distinct from the first.',
  },
  {
    id: 'synthetic-low-quality',
    file: 'synthetic-low-quality.png',
    mediaType: 'image/png',
    description: 'A low-contrast, fine-grained field with no resolvable edge: an image a plausible observer reports as unassessable.',
  },
]

/** The directory the registry's files live in, resolved the same way from `src/` and from the built `lib/`. */
const FIXTURE_DIRECTORY = fileURLToPath(new URL('../fixtures/images/', import.meta.url))

/** One fixture's bytes, as the runner admits them. */
export interface LoadedImageFixture {
  /** The registry id this was loaded under. */
  readonly id: string
  /** Media type to declare at admission, verified there against the bytes. */
  readonly mediaType: ImageMediaType
  /** Exact file bytes. */
  readonly bytes: Uint8Array
}

/**
 * Every fixture id the registry holds, in table order.
 * @returns the ids a golden case may name.
 */
export function fixtureIds(): readonly string[] {
  return FIXTURES.map(entry => entry.id)
}

/**
 * Read one fixture's bytes.
 *
 * The id is looked up in the closed table rather than joined into a path, so a
 * case cannot name a file this package does not own — not by traversal, not by
 * an absolute path, and not by a name that merely looks like one.
 * @param id - the registry id a golden case named.
 * @returns the fixture's bytes and declared media type.
 * @throws {@link GoldenCaseError} when the id is not in the registry.
 */
export function loadImageFixture(id: string): LoadedImageFixture {
  const entry = FIXTURES.find(candidate => candidate.id === id)
  if (entry === undefined) {
    throw new GoldenCaseError(
      `unknown image fixture ${JSON.stringify(id)}; the registry holds ${FIXTURES.map(candidate => candidate.id).join(', ')}`,
    )
  }
  return { id: entry.id, mediaType: entry.mediaType, bytes: readFileSync(`${FIXTURE_DIRECTORY}${entry.file}`) }
}

/**
 * What one registry entry says about itself, for documentation and for a test
 * that pins the table against the files on disk.
 * @returns every entry's id, file, media type, and description.
 */
export function fixtureCatalog(): readonly {
  readonly id: string
  readonly file: string
  readonly mediaType: ImageMediaType
  readonly description: string
}[] {
  return FIXTURES.map(entry => ({ ...entry }))
}
